import { GameText } from '../../../core/game-text';
/* tslint:disable:max-line-length */
/** Values up to and including `end` are in this range; `state` is the range's state number. */
export interface TerraformingRangeData {
  end: number;
  state: number;
  /** habitable="false" */
  notHabitable?: true;
  /** #rrggbb */
  color: string;
  description?: string;
}

export interface TerraformingStatData {
  id: string;
  version: number;
  name: string;
  default: number;
  dynamic?: true;
  icon?: string;
  /** inactivetext, e.g. "No oxygen detected" */
  text?: string;
  ranges: TerraformingRangeData[];
}

export interface TerraformingGroupData {
  id: string;
  name: string;
}

/** min/max: of the stat's range state; minValue/maxValue: of its value */
export interface TerraformingConditionData {
  stat: string;
  min?: number;
  max?: number;
  minValue?: number;
  maxValue?: number;
}

/** change: added to the stat's value; value: the value set; min/max as the library gives them */
export interface TerraformingEffectData {
  stat: string;
  change?: number;
  value?: number;
  min?: number;
  max?: number;
}

export interface TerraformingSideEffectData {
  /** % */
  chance: number;
  /** % */
  setback?: number;
  project?: string;
  text?: string;
  /** beneficial="false" */
  harmful?: true;
  stat?: string;
  change?: number;
}

/** value: % */
export interface TerraformingRebateData {
  ware?: string;
  wareGroup?: string;
  value: number;
}

export interface TerraformingDeliveryData {
  macro: string;
  name?: string;
  amount: number;
  /** seconds */
  buildDuration: number;
}

export interface TerraformingProjectData {
  id: string;
  version: number;
  group: string;
  name: string;
  description?: string;
  /** seconds */
  duration?: number;
  /** repeatcooldown, seconds: set when the project can be repeated */
  repeatCooldown?: number;
  resilient?: true;
  /** chance of success, % */
  chance?: number;
  research?: string;
  conditions: TerraformingConditionData[];
  effects: TerraformingEffectData[];
  sideEffects: TerraformingSideEffectData[];
  rebates: TerraformingRebateData[];
  /** Credits unless priceScale is set */
  price?: number;
  priceScale?: string;
  maxPrice?: number;
  payout?: number;
  minWares?: number;
  maxWares?: number;
  /** the amounts of the library's resources element */
  wares: { ware: string; amount: number }[];
  deliveries: TerraformingDeliveryData[];
  /** removedprojects */
  removes: string[];
  /** blockedprojects */
  blocks: string[];
  /** blockedgroups */
  blocksGroups: string[];
}

/** A project an md script adds to the planet, with its predecessors; any: any one of them. */
export interface TerraformingPlanetProjectData {
  id: string;
  predecessors: string[];
  any?: true;
}

/** A planet an md script initialises for terraforming, with the literal stats, projects and events it sets. */
export interface TerraformingPlanetData {
  cluster: string;
  part: string;
  /** index in the cluster's planets, -1 when not found */
  planet: number;
  /** index in that planet's moons when the terraformed body is a moon */
  moon?: number;
  name?: string;
  version: number;
  stats: { stat: string; value: number }[];
  projects: TerraformingPlanetProjectData[];
  events: string[];
  /** md file and line */
  source: string;
}

export interface TerraformingDataSet {
  stats: TerraformingStatData[];
  groups: TerraformingGroupData[];
  projects: TerraformingProjectData[];
  planets: TerraformingPlanetData[];
  /** the game's terraforming menu texts */
  labels: Record<string, { label: string }>;
}

